def validate_story_start_path_41_50() -> None:
    quests=STORY_START_PATH_41_50
    if len(quests)!=10 or [q.number for q in quests]!=list(range(41,51)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='start_path_040_before_the_final_hunt': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=5 or quest.location_id!='start_path': raise ValueError('invalid_level_or_location')
        if quest.reward_exp < 0 or quest.reward_gold < 0: raise ValueError('invalid_reward')
    if quests[8].quest_type!='BOSS' or quests[9].quest_type!='TURN_IN': raise ValueError('invalid_terminal_contract')

validate_story_start_path_41_50()
